program='''from collections import Counter

def transform(grid):
    """Fill background cells between aligned marker cells with color 3."""
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        marks = [c for c, value in enumerate(grid[r]) if value != background]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != background]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = 3
    return out
'''
